SELECT SUM(CASE WHEN CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) > s.promised_date THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS v FROM shipments s WHERE s.delivered_at_utc IS NOT NULL AND s.order_id IN (SELECT order_id FROM orders WHERE is_deleted = FALSE) AND s.delivered_at_utc >= (TIMESTAMP '2026-01-01 00:00:00' - INTERVAL 6 HOUR) AND s.delivered_at_utc < (TIMESTAMP '2026-11-01 00:00:00' - INTERVAL 6 HOUR)
